(()=>{'use strict';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function main(){const response=await fetch('/attachment-group-candidate-20261026.json',{cache:'no-store'});if(!response.ok)throw Error('HTTP '+response.status);const data=await response.json();if(data.schema!=='o-attachment-group-independent-v1')throw Error('数据版本不符');
const host=document.querySelector('#main'),slot=(parts,back=false)=>`<div class="slots">${parts.map((x,i)=>`<div class="slot"><small>${back?'后置显示':'规范语义'}第${i+1}格</small><strong>${esc(x)}</strong></div>`).join('')}</div>`;
host.innerHTML=`<section><h2>1. 哪些已经能按键查？</h2><div class="notice">现行 <code>iots</code> 选圆主体下方的点；<code>ioyw</code> 选圆主体上方的线状附件，本字是折线。两条都仍需先认圆主体，不是完全绕过主体的附件起手。</div><div class="scroll"><table><thead><tr><th>所选对象</th><th>规范前置</th><th>后置</th><th>当前快照人数／目标位次</th></tr></thead><tbody>${data.realEntries.map(e=>`<tr><td>${e.canonical==='iots'?'下方点块':'上方折线'}</td><td><code>${e.canonical}</code></td><td><code>${e.back}</code></td><td>${e.count}／${e.rank}</td></tr>`).join('')}</tbody></table></div><p><code>i</code> 按圆主体取闭环均衡桶；<code>o</code> 圆主体；<code>t</code> 点块、<code>y</code> 线状附件；<code>s</code> 下方、<code>w</code> 上方，位置相对该圆主体。第三、第四位描述同一选定附件。后置只是换序，不增加一路。</p><div class="controls">${data.realEntries.flatMap((e,i)=>['front','back'].map(order=>`<button data-real-index="${i}" data-order="${order}">实际试查 ${order==='front'?e.canonical:e.back}</button>`)).join('')}</div><p id="real-status" class="status" role="status"></p><div id="real-candidates" class="candidate-grid"></div><p class="muted">两个真实集合的只读交集当前只有ộ；这不是一个新联合码，也不能证明“恰好2件”或“y一定为折线”。本页不把两个四码拼作一个编码。</p><p class="muted">快照${esc(new Date(data.capturedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}))} · ${esc(data.runtimeVersion)}＋${esc(data.shapeBoundaryRefinement)}。原首选epki保留。</p></section><section><h2>2. “2附件”和“3个墨部件”不同</h2><p>蓝框为圆主体，橙框为主体外附件。ộ的折角虽然含两条线段，仍是<strong>一个附件</strong>；附件组只包含折线和点，不包含圆主体。</p><div class="samples" id="samples">${data.sample.map(r=>`<article class="sample" data-char="${esc(r.char)}"><div class="sample-img"><img src="${r.image}" alt="${esc(r.char)}锁定原字形"><svg viewBox="0 0 64 64" aria-hidden="true"><rect x="${r.bodyBBox[0]}" y="${r.bodyBBox[1]}" width="${r.bodyBBox[2]-r.bodyBBox[0]}" height="${r.bodyBBox[3]-r.bodyBBox[1]}" fill="none" stroke="#2874a8" stroke-width=".7"/>${r.members.map(m=>`<rect x="${m.bbox[0]}" y="${m.bbox[1]}" width="${m.bbox[2]-m.bbox[0]}" height="${m.bbox[3]-m.bbox[1]}" fill="#b66f25" fill-opacity=".1" stroke="#b66f25" stroke-width=".7"/>`).join('')}</svg></div><span class="sample-name">${esc(r.char)}</span><p>外附件 ${r.externalCount}件<br>${esc(r.members.map(m=>m.position+'方'+m.type).join('＋')||'无外附件')}<br><small>全字墨部件 ${r.totalInkParts}件</small></p></article>`).join('')}</div><p class="muted">只有ộ的两附件类型为本人已确认；其余6字仅作锁定图AI对照，不批量派码或宣称跨字体已稳定。</p><div class="controls"><label for="sim-condition">模拟比较条件（仅7例）</label><select id="sim-condition">${data.simulations.map((s,i)=>`<option value="${i}">${esc(s.label)}</option>`).join('')}</select></div><p id="sim-status" class="status" role="status"></p><div class="notice warning">模拟结果只对应这7例，不是全库候选数。类型只分“点＋线状”时，ộ和ȱ都符合；分“折线＋点”才区分ȱ的“横短线＋点”。上下排列也是同一个附件组的属性，不能C选整组、D却只借某个附件的孤立属性。</div><details><summary>为什么不能直接借用旧k或n？</summary><p>现行<code>iokb</code>为${data.currentGroupBaseline.iokb.count}候选，ô/ọ已在其中：它们是主体＋1附件共2件，而不是2外附件。把b叫作“2附件”会误解原成员。</p><p>保持旧k对象范围时，ộ应数主体＋折线＋点共3件。若只为本字新增<code>iokt</code>，预测${data.currentGroupBaseline.iokt.count}→${data.currentGroupBaseline.iokt.ifOnlyAddTarget}人；这要求将2附件心算成3，且没有同时表达折线＋点。这里没有实际新增该码。</p><p><code>n</code>仍限相似分离构件，折线和点不是同类，不能静默扩义。有效第三位26键都有用途；基础表a/b/g/j/q的零占位不是真正空键。</p></details></section><section><h2>3. 两个四格语义方案</h2><p class="error"><strong>以下都是不可输入的语义占位式，尚未分配字母，不是新码。</strong> 两方案都保持A=i、B=o。C/D选择同一附件组；字母、与8孔组的共用框架及末位容量由总控统一决定。</p>${data.proposals.map(p=>`<article class="proposal ${p.recommended?'recommended':''}" data-proposal="${p.id}"><span class="tag">方案${p.id}${p.recommended?' · 优先建议':''}</span><h3>${esc(p.name)}</h3>${slot(p.canonicalSemanticSlots)}<p>${esc(p.advantage)}</p><p class="muted">代价：${esc(p.cost)}</p><details><summary>后置四格及同组排列替代式</summary>${slot(p.backSemanticSlots,true)}<p>同一组的另一完整码可用：</p>${slot(p.alternateSameObjectSlots)}<p class="muted">这不是在完整四码后再追加第5位；类型和排列是同一主思路的不同属性码，不自动增加独立查找思路。</p></details></article>`).join('')}<div class="notice">A把“二件”固定在第三格的对象条件中，末格可直接选“折线＋点”。B的末格每次选一种组属性；输入“2件”后还想看类型，须替换末格或改用另一条同组码，不能继续追加字符。</div><p>如果A首批仅给ộ一个类型组合入口，条件无冲突且正式获准后才可能从现有${data.target.paths.length}路变为${data.target.paths.length+1}路；A再加一个组排列码则${data.target.paths.length+2}路。B若数量、类型各一条则${data.target.paths.length+2}路，再加排列则${data.target.paths.length+3}路。均只是路径预算，不是已发生的差异，全库新码候选数未知。</p><p class="muted">若点/短直线/折线/曲线4类的二件无序组合全列，会有10类；再叠3种排列就是30种标签。不能假设一格26字母能无限装下全部组合，不作泛化承诺。</p></section><section><h2>4. 只需两个新的编码取舍（可选填）</h2><p>不是重新确认“圆＋2附件”是否自然；该点已接受。这里的选择先交总控比较公共键义和8专项，不立即改码。</p><label class="choice"><input type="radio" name="packaging" value="A">方案A：前三格已限定二件外附件组，末格选折线＋点</label><label class="choice"><input type="radio" name="packaging" value="B">方案B：前三格选外附件组，末格在数量／类型／排列之间选择</label><label class="choice"><input type="radio" name="packaging" value="defer">暂不能定，先看公共键义如何安排</label><label>首批落实范围<select id="first-scope"><option value="">尚未选择</option><option value="types-only">优先类型组合；上下位置继续使用现有单附件入口（建议）</option><option value="types-and-layout">类型组合与同组上下排列都准备完整码</option><option value="defer">待统一键义和候选代价后再定</option></select></label><label>补充<textarea id="note" rows="3" placeholder="可以写具体希望怎样输入；不必重答旧24题"></textarea></label><div class="controls"><button id="copy">复制本处选择</button><button id="download">下载JSON</button></div><p class="status" id="feedback-status" role="status"></p><textarea id="fallback" readonly rows="7" hidden aria-label="可复制的候选选择"></textarea><p class="muted">独立草稿；不覆盖旧24字、附件说明或笔数说明的草稿，不写人工审议和运行绑定。</p></section><section><h2>范围与未完成项</h2><p>本次只给ộ准备独立语义候选；7字对照、有限集合模拟、现行两码与换序可达已核。新组键义、类型检测推广、实际新字母、全库候选数、与8的冲突消解、正式首选和集成仍未完成。</p><p>圆主体七例只是证据收尾，仍有遗留；本材料没有将其宣称全修复。没有增删旧码、不改首选、不启用新公共键义；未重启服务、部署或推送。</p></section>`;
const sim=document.querySelector('#sim-condition');function update(){const s=data.simulations[Number(sim.value)];host.querySelectorAll('.sample').forEach(el=>el.classList.toggle('active',s.characters.includes(el.dataset.char)));document.querySelector('#sim-status').textContent=`仅这7例：${s.label} → ${s.count}字（${s.characters.join('、')||'无'}）；不是当前运行码候选人数。`}sim.onchange=update;update();
let token=0;host.querySelectorAll('[data-real-index]').forEach(btn=>btn.onclick=async()=>{const index=Number(btn.dataset.realIndex),entry=data.realEntries[index],back=btn.dataset.order==='back',code=back?entry.back:entry.canonical,t=++token,st=document.querySelector('#real-status'),grid=document.querySelector('#real-candidates');st.textContent='读取当前候选…';grid.replaceChildren();try{const params=new URLSearchParams({allocation:'1',prefix:code});if(back){params.set('order','back');params.set('routeLength','4')}const res=await fetch('/api/shape-overview/query?'+params);if(!res.ok)throw Error('HTTP '+res.status);const q=await res.json();if(t!==token)return;st.textContent=`${code} 当前${q.total}候选；点击ộ核对。`;for(const [i,row] of q.rows.entries()){const b=document.createElement('button');b.className='candidate';const span=document.createElement('span');span.className='sprite';span.setAttribute('role','img');span.setAttribute('aria-label',row.char);if(row.preview){span.style.backgroundImage=`url("/${row.preview.url}")`;span.style.backgroundPosition=`-${row.preview.x}px -${row.preview.y}px`}else span.textContent=row.char;const label=document.createElement('span');label.textContent='U+'+row.cp.toString(16).toUpperCase();b.append(span,label);b.onclick=()=>{if(row.cp===0x1ed9){b.classList.add('found');st.textContent=`已找到ộ：${code}，${q.total}候选，第${i+1}位；仍是先圆主体后单附件。`}else st.textContent='不是目标ộ，可继续点选。'};grid.append(b)}}catch(e){if(t!==token)return;st.textContent='实时服务读取失败：'+e.message+'；模拟结果仍只是独立材料。'}});
const key='o-attachment-group-design-feedback-20261026',draft={schema:'o-attachment-group-design-feedback-v1',packaging:'',firstScope:'',note:''};try{const old=JSON.parse(localStorage.getItem(key)||'null');if(old?.schema===draft.schema)for(const k of ['packaging','firstScope','note'])if(typeof old[k]==='string')draft[k]=old[k]}catch{}const persist=()=>{draft.updatedAt=new Date().toISOString();try{localStorage.setItem(key,JSON.stringify(draft));document.querySelector('#feedback-status').textContent='独立草稿已保存，旧页面草稿未动。'}catch{document.querySelector('#feedback-status').textContent='浏览器保存不可用，请复制或下载本处选择。'}};host.querySelectorAll('input[name=packaging]').forEach(el=>{el.checked=el.value===draft.packaging;el.onchange=()=>{draft.packaging=el.value;persist()}});document.querySelector('#first-scope').value=draft.firstScope;document.querySelector('#first-scope').oninput=e=>{draft.firstScope=e.target.value;persist()};document.querySelector('#note').value=draft.note;document.querySelector('#note').oninput=e=>{draft.note=e.target.value;persist()};const text=()=>JSON.stringify({...draft,evidenceCapturedAt:data.capturedAt,status:'ộ附件组独立编码取舍，未批准字母分配、改码或首选；待总控统一冲突',exportedAt:new Date().toISOString()},null,2);document.querySelector('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(text());document.querySelector('#feedback-status').textContent='已复制，可交回当前总控。'}catch{const el=document.querySelector('#fallback');el.hidden=false;el.value=text();el.focus();el.select();document.querySelector('#feedback-status').textContent='请手动复制或下载JSON。'}};document.querySelector('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([text()],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='ộ附件组编码取舍.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
}main().catch(e=>{document.querySelector('#main').textContent='独立材料读取失败：'+e.message+'；原有审核与草稿未更改。'});})();
